@once
<style>
.tracking-shell{max-width:1040px;margin:.5rem auto}.tracking-head{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin-bottom:1rem}.tracking-head h1{margin:.15rem 0 .35rem}.tracking-meta,.tracking-actions{display:flex;align-items:center;flex-wrap:wrap;gap:.65rem}.tracking-progress,.tracking-history{padding:1.15rem}.tracking-progress{margin-bottom:1rem;overflow:hidden}.tracking-steps{display:grid;grid-template-columns:repeat(6,1fr);list-style:none;padding:0;margin:.8rem 0 0}.tracking-steps li{position:relative;padding:1.15rem .35rem 0 0;color:var(--z-muted);font-size:.74rem;font-weight:700}.tracking-steps li:before{content:'';position:absolute;z-index:1;top:0;left:0;width:10px;height:10px;border:3px solid #fff;border-radius:50%;background:var(--z-border);box-sizing:content-box}.tracking-steps li:after{content:'';position:absolute;top:6px;left:10px;right:0;height:2px;background:var(--z-border)}.tracking-steps li:last-child:after{display:none}.tracking-steps li.is-done:before,.tracking-steps li.is-done:after{background:var(--z-primary)}.tracking-history h2{margin-top:0}.tracking-footer{margin-top:1rem}
@media(max-width:767px){.tracking-head{display:grid;align-items:start}.tracking-steps{display:flex;flex-direction:column;margin-left:.2rem}.tracking-steps li{padding:0 0 1rem 1.5rem}.tracking-steps li:after{top:10px;bottom:-2px;left:7px;width:2px;height:auto}.tracking-shell,.tracking-shell>*{min-width:0}.tracking-actions{width:100%}.tracking-actions .z-btn{flex:1 1 auto;justify-content:center}}
</style>
@endonce
